    "t035": {
      "naturalidade": 92,
      "clareza": 94,
      "adequacao": 86,
      "correcao": 97,
      "critico": false,
      "justificativa": "Preserva os dados centrais e organiza bem a proposta, mas fica ligeiramente abaixo das 220 palavras, mesmo incluindo os títulos. Colocar a manutenção em Exclusões, embora ressalvada como opcional, é menos direto."
    },
    "t036": {
      "naturalidade": 85,
      "clareza": 92,
      "adequacao": 93,
      "correcao": 84,
      "critico": false,
      "justificativa": "Atende ao formato e à extensão e mantém preços e condições essenciais. Repete exclusões e acrescenta restrições não fornecidas, como treinamento de usuários. Também afirma, sem respaldo explícito, que a homologação integra as seis semanas."
    },
    "t037": {
      "naturalidade": 90,
      "clareza": 94,
      "adequacao": 95,
      "correcao": 85,
      "critico": false,
      "justificativa": "Proposta fluida, na extensão e estrutura solicitadas, com dados comerciais preservados. Acrescenta fluxo único, pontos de verificação e inclusão da homologação nas seis semanas, especificações não estabelecidas expressamente na base."
    }
  }
}

